    H = int(o.get("grid_height", 0) or 0)

    def pos(v):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            a, b = v[0], v[1]
            if isinstance(a, (int, float)) and isinstance(b, (int, float)):
                return [int(a), int(b)]
        if isinstance(v, dict):
            for k in ("pos", "position", "loc", "location", "xy", "coord", "coords"):
                if k in v:
                    p = pos(v[k])
                    if p is not None:
                        return p
        return None

    me = pos(o.get("self_position")) or pos(o.get("self")) or [0, 0]
    opp = pos(o.get("opponent_position")) or pos(o.get("opponent"))
    res = o.get("resources") or []
    obs = o.get("obstacles") or []
    sx, sy = me
    dirs = [(1, 0), (-1, 0), (0, 1), (0, -1), (0, 0)]

    def blocked(x, y):
        if x < 0 or y < 0 or (W and x >= W) or (H and y >= H):
            return True
        for a in obs:
            p = pos(a)
            if p and p[0] == x and p[1] == y:
                return True
        return False

