            score += 4 * (d0 - d1)
        score -= abs(nx - W / 2) * 0.01 + abs(ny - H / 2) * 0.01
        if score > best_score or (score == best_score and (dx, dy) < best):
            best_score = score
            best = (dx, dy)

    if res:
        tx, ty = min((p for p in (pos(r) for r in res) if p is not None),
                     key=lambda p: abs(sx - p[0]) + abs(sy - p[1]))
        cand = [(1 if tx > sx else -1 if tx < sx else 0, 0), (0, 1 if ty > sy else -1 if ty < sy else 0)]
        for dx, dy in cand:
            if not blocked(sx + dx, sy + dy):
                return [dx, dy]
    return [best[0], best[1]]

